// Takes the payment of an order through the gateway. Called by the pay button (src/ui/pay-button.js).
// A second call for the same order while the first is still running gets the first call's receipt:
// the button can be pressed twice before the page re-renders, and a customer must never be charged twice.
export function createCapture(gateway) {
  const running = new Map(); // order id -> the charge still on its way

  async function charge(order) {
    const receipt = await gateway.charge(order.id, order.total);
    order.paid = true;
    order.receipt = receipt;
    return receipt;
  }

  return async function capture(order) {
    if (order.paid) return order.receipt;
    if (!running.has(order.id)) {
      // Forgotten when it ends, also when it fails: a failed payment can be tried again.
      running.set(order.id, charge(order).finally(() => running.delete(order.id)));
    }
    return running.get(order.id);
  };
}

