import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createCapture } from '../../src/checkout/capture.js';
import { createSandboxGateway } from '../../src/gateway.js';

test('an order is charged and marked paid', async () => {
  const gateway = createSandboxGateway();
  const capture = createCapture(gateway);
  const order = { id: 'o-1', total: 1200 };
  const receipt = await capture(order);
  assert.equal(order.paid, true);
  assert.equal(receipt.amount, 1200);
  assert.equal(gateway.charges.length, 1);
});

test('a paid order is not charged again', async () => {
  const gateway = createSandboxGateway();
  const capture = createCapture(gateway);
  const order = { id: 'o-2', total: 800 };
  await capture(order);
  await capture(order);
  assert.equal(gateway.charges.length, 1);
});

// Issue #43: the pay button can be pressed twice before the first result is back.
test('an order paid twice before the first result is back is charged once, and both get the same receipt', async () => {
  const gateway = createSandboxGateway();
  const capture = createCapture(gateway);
  const order = { id: 'o-3', total: 1500 };
  const [first, second] = await Promise.all([capture(order), capture(order)]);
  assert.deepEqual(gateway.charges, [{ id: 'ch_1', orderId: 'o-3', amount: 1500 }]);
  assert.deepEqual(first, { id: 'ch_1', orderId: 'o-3', amount: 1500 });
  assert.strictEqual(second, first);
  assert.equal(order.paid, true);
});

test('an order whose charge failed is not marked paid and can be paid again', async () => {
  const sandbox = createSandboxGateway();
  let down = true;
  const gateway = {
    async charge(orderId, amount) {
      if (down) throw new Error('gateway is down');
      return sandbox.charge(orderId, amount);
    },
  };
  const capture = createCapture(gateway);
  const order = { id: 'o-4', total: 900 };
  await assert.rejects(capture(order), /gateway is down/);
  assert.equal(order.paid, undefined);
  down = false;
  const receipt = await capture(order);
  assert.deepEqual(receipt, { id: 'ch_1', orderId: 'o-4', amount: 900 });
  assert.deepEqual(sandbox.charges, [{ id: 'ch_1', orderId: 'o-4', amount: 900 }]);
});

test('different orders paid at the same time are each charged, each with its own receipt', async () => {
  const gateway = createSandboxGateway();
  const capture = createCapture(gateway);
  const [first, second] = await Promise.all([capture({ id: 'o-5', total: 300 }), capture({ id: 'o-6', total: 700 })]);
  assert.deepEqual(first, { id: 'ch_1', orderId: 'o-5', amount: 300 });
  assert.deepEqual(second, { id: 'ch_2', orderId: 'o-6', amount: 700 });
  assert.equal(gateway.charges.length, 2);
});

