import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createPayButton } from '../../src/ui/pay-button.js';
import { createCapture } from '../../src/checkout/capture.js';
import { createSandboxGateway } from '../../src/gateway.js';

test('a click takes the payment and shows the receipt number', async () => {
  const shown = [];
  const button = createPayButton({
    capture: async (order) => ({ id: 'ch_1', orderId: order.id, amount: order.total }),
    order: { id: 'o-1', total: 1200 },
    show: (text) => shown.push(text),
  });
  await button.click();
  assert.deepEqual(shown, ['Paid: ch_1']);
});

// Issue #43, as the customer does it: the real capture behind the button, and the sandbox gateway.
test('two clicks before the first result is back charge the order once and show the same receipt', async () => {
  const gateway = createSandboxGateway();
  const shown = [];
  const button = createPayButton({
    capture: createCapture(gateway),
    order: { id: 'o-2', total: 1200 },
    show: (text) => shown.push(text),
  });
  await Promise.all([button.click(), button.click()]);
  assert.deepEqual(gateway.charges, [{ id: 'ch_1', orderId: 'o-2', amount: 1200 }]);
  assert.deepEqual(shown, ['Paid: ch_1', 'Paid: ch_1']);
});

